<?php
namespace App\Http\Controllers;
use App\Models\Arsip;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Storage;
class ArsipController extends Controller { public function index(Request $r){$q=$r->string('q');$data=Arsip::when($q,fn($x)=>$x->where('kode','like',"%$q%")->orWhere('nama','like',"%$q%")->orWhere('kategori','like',"%$q%"))->latest('tanggal')->paginate(15)->withQueryString();return view('arsip.index',compact('data','q'));} public function create(){return view('arsip.form',['item'=>new Arsip]);} public function store(Request $r){$d=$r->validate(['kode'=>'required','nama'=>'required','kategori'=>'nullable','tanggal'=>'nullable|date','lokasi'=>'nullable','keterangan'=>'nullable','file'=>'nullable|file|max:10240']);if($r->hasFile('file'))$d['file_path']=$r->file('file')->store('arsip','public');unset($d['file']);Arsip::create($d);return redirect()->route('arsip.index')->with('success','Arsip berhasil disimpan.');} public function edit(Arsip $arsip){return view('arsip.form',['item'=>$arsip]);} public function update(Request $r,Arsip $arsip){$d=$r->validate(['kode'=>'required','nama'=>'required','kategori'=>'nullable','tanggal'=>'nullable|date','lokasi'=>'nullable','keterangan'=>'nullable','file'=>'nullable|file|max:10240']);if($r->hasFile('file')){if($arsip->file_path)Storage::disk('public')->delete($arsip->file_path);$d['file_path']=$r->file('file')->store('arsip','public');}unset($d['file']);$arsip->update($d);return redirect()->route('arsip.index')->with('success','Arsip diperbarui.');} public function destroy(Arsip $arsip){if($arsip->file_path)Storage::disk('public')->delete($arsip->file_path);$arsip->delete();return back()->with('success','Arsip dihapus.');} }
